/* Atlas service worker.
 *
 * Its ONLY job is to make the app installable and to survive a dropped
 * connection. It is deliberately not an offline-first cache: this app's data
 * lives in Postgres on the server, and a stale view of someone's document
 * library is worse than an honest "you are offline".
 *
 * Written by hand rather than generated by Workbox because the caching rules
 * below are four lines of policy, and a build-time plugin would put a
 * dependency (and a generated precache manifest) into a repo that carries
 * neither.
 *
 * ---------------------------------------------------------------------------
 * THE RULES, and why each one is what it is
 *
 *  /api/*        NEVER INTERCEPTED. Not cached, not read, not touched -- the
 *                request is left to the browser exactly as if no worker were
 *                installed. Every one of these is live, authenticated, or
 *                both: job state, previews streamed with Range headers, the
 *                JWT refresh. A worker sitting in front of them can only
 *                introduce staleness and confusion.
 *
 *  navigations   NETWORK-FIRST, cache only as an offline fallback. This is the
 *                same rule backend/src/app.js already enforces with
 *                `Cache-Control: no-cache` on index.html, and for the same
 *                hard-won reason: a stale index.html points at asset hashes
 *                that no longer exist after a rebuild, and the app renders as
 *                a blank page with the correct title. Network-first means a
 *                rebuild is picked up on the very next load.
 *
 *  /assets/*     CACHE-FIRST. Vite fingerprints these, so the bytes behind a
 *                given filename can never change -- the same reasoning that
 *                lets app.js serve them `immutable`. Safe to serve from cache
 *                forever; old hashes are evicted with the cache version.
 *
 *  everything    STALE-WHILE-REVALIDATE. Icons, the manifest, favicon. Small,
 *  else          rarely changed, and not worth a network round trip on load.
 *
 *  cross-origin  NOT INTERCEPTED. Google Fonts answers with opaque responses
 *                whose success we cannot inspect, so caching them risks
 *                pinning a failure.
 * ---------------------------------------------------------------------------
 *
 * IF THIS EVER MISBEHAVES ON A DEPLOYED MACHINE, the escape hatch is one line
 * in the browser console -- no DevTools archaeology, no reinstall:
 *
 *   navigator.serviceWorker.getRegistrations().then(r => r.forEach(x => x.unregister()))
 *
 * then a hard refresh. Bumping CACHE_VERSION below also discards every cached
 * byte on the next load.
 */

// Bump to invalidate every cache this worker owns.
const CACHE_VERSION = "v1";
const CACHE_NAME = `atlas-${CACHE_VERSION}`;

// The one document worth having before the network is gone. Not a full
// precache list: the hashed assets are cached as they are actually requested,
// which keeps this worker from needing to know the build's output filenames.
const OFFLINE_DOCUMENT = "/";

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      // `cache: "reload"` bypasses the HTTP cache so a fresh install cannot
      // seed itself with the very stale index.html it exists to avoid.
      await cache.add(new Request(OFFLINE_DOCUMENT, { cache: "reload" }));
    })()
  );

  // Activate immediately instead of waiting for every tab to close.
  //
  // The usual argument against this is that a page can end up running old
  // JavaScript against a new worker. It does not apply here: assets are
  // content-hashed, so a running page keeps fetching the exact filenames it
  // was built with, and the next navigation gets the new index.html from the
  // network. The argument FOR it is concrete -- on a self-hosted deployment
  // nobody closes every tab, so without this a rebuild could sit unapplied
  // indefinitely behind a worker stuck in `waiting`.
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((name) => name.startsWith("atlas-") && name !== CACHE_NAME).map((name) => caches.delete(name))
      );
      await self.clients.claim();
    })()
  );
});

self.addEventListener("message", (event) => {
  // Lets the page trigger the two things worth triggering from outside.
  if (event.data === "SKIP_WAITING") self.skipWaiting();
  if (event.data === "UNREGISTER") self.registration.unregister();
});

/** Only same-origin GETs are ever eligible for caching. */
function isCacheable(response) {
  return response && response.ok && response.type === "basic";
}

async function networkFirstDocument(request) {
  const cache = await caches.open(CACHE_NAME);
  try {
    const response = await fetch(request);
    if (isCacheable(response)) {
      // Store under the offline document key, not the requested URL: every
      // client-side route resolves to the same index.html, so caching one
      // entry per visited route would just be duplicates of one file.
      cache.put(OFFLINE_DOCUMENT, response.clone());
    }
    return response;
  } catch {
    const cached = await cache.match(OFFLINE_DOCUMENT);
    if (cached) return cached;
    return new Response(
      "<!doctype html><meta charset=utf-8><title>Atlas is offline</title>" +
        "<body style=\"font:16px system-ui;background:#08090d;color:#e6e7ea;padding:3rem\">" +
        "<h1>Atlas is offline</h1><p>The Atlas server could not be reached. " +
        "It runs on the machine your documents are on -- check that machine is awake, " +
        "then reload.</p>",
      { status: 503, headers: { "Content-Type": "text/html; charset=utf-8" } }
    );
  }
}

async function cacheFirst(request) {
  const cache = await caches.open(CACHE_NAME);
  const cached = await cache.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (isCacheable(response)) cache.put(request, response.clone());
  return response;
}

async function staleWhileRevalidate(request) {
  const cache = await caches.open(CACHE_NAME);
  const cached = await cache.match(request);

  const network = fetch(request)
    .then((response) => {
      if (isCacheable(response)) cache.put(request, response.clone());
      return response;
    })
    // An offline revalidation must not surface as an unhandled rejection when
    // we already served the cached copy.
    .catch(() => cached);

  return cached || network;
}

self.addEventListener("fetch", (event) => {
  const { request } = event;

  // Anything that is not a plain GET is the app talking to the server.
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // Cross-origin (fonts) -- leave alone.
  if (url.origin !== self.location.origin) return;

  // The API is off limits, see the header comment.
  if (url.pathname.startsWith("/api/")) return;

  if (request.mode === "navigate") {
    event.respondWith(networkFirstDocument(request));
    return;
  }

  if (url.pathname.startsWith("/assets/")) {
    event.respondWith(cacheFirst(request));
    return;
  }

  event.respondWith(staleWhileRevalidate(request));
});
